"""Seeds the synthetic demo dataset (generated by wastewise.demo_data)."""
from __future__ import annotations

from datetime import date

from . import db
from .demo_data import DEMO_SEED, DEMO_START, generate_dataset


def seed_demo(conn, *, start: date = DEMO_START, weeks: int = 8,
              rng_seed: int = DEMO_SEED) -> dict:
    """Idempotent: removes earlier synthetic rows, then inserts the generated dataset."""
    ds = generate_dataset(start, weeks, rng_seed)
    db.clear_synthetic(conn)
    db.bulk_insert_synthetic(conn, ds["waste_logs"], ds["meal_counts"], ds["item_costs"],
                             ds["interventions"])
    return {"waste_rows": len(ds["waste_logs"]), "count_rows": len(ds["meal_counts"]),
            "days": weeks * 7}


def seed_if_empty(conn) -> bool:
    """Seed the demo dataset only when the database holds no logs, counts or interventions."""
    n = sum(conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
            for t in ("waste_logs", "meal_counts", "interventions"))
    if n:
        return False
    seed_demo(conn)
    return True
